func (this *Combo) GetSelection() *Point {
	this.CheckWidget()
	if (this.style & READ_ONLY) != 0 {
		var length int32 = 0
		var index int32 = gtk.GTKGtk_combo_box_get_active(this.Handle)
		if index != -1 {
			length = jrt.StringLength(this.GetItem(index))
		}
		return NewPoint(0, length)
	}
	var start []int32 = make([]int32, 1)
	var end []int32 = make([]int32, 1)
	if this.entryHandle != 0 {
		gtk.GTKGtk_editable_get_selection_bounds(this.entryHandle, start, end)
		var ptr int64
		if gtk.GTKGTK4 {
			ptr = gtk.GTK4Gtk_entry_buffer_get_text(gtk.GTK4Gtk_entry_get_buffer(this.entryHandle))
		} else {
			ptr = gtk.GTK3Gtk_entry_get_text(this.entryHandle)
		}
		start[0] = int32(gtk.OSG_utf8_offset_to_utf16_offset(ptr, int64(start[0])))
		end[0] = int32(gtk.OSG_utf8_offset_to_utf16_offset(ptr, int64(end[0])))
	}
	return NewPoint(start[0], end[0])
}

func (this *Combo) GetSelectionIndex() int32 {
	this.CheckWidget()
	return gtk.GTKGtk_combo_box_get_active(this.Handle)
}

func (this *Combo) GetText() string {
	this.CheckWidget()
	if this.entryHandle != 0 {
		var str int64 = int64(0)
		if gtk.GTKGTK4 {
			var bufferHandle int64 = gtk.GTK4Gtk_entry_get_buffer(this.entryHandle)
			str = gtk.GTKGtk_entry_buffer_get_text(bufferHandle)
		} else {
			str = gtk.GTK3Gtk_entry_get_text(this.entryHandle)
		}
		if str == 0 {
			return ""
		} else {
			var length int32 = gtk.CStrlen(str)
			var buffer []int8 = make([]int8, length)
			gtk.CMemmoveOverload8(buffer, str, int64(length))
			return jrt.FromChars(gtk.ConverterMbcsToWcs(buffer))
		}
	} else {
		var index int32 = gtk.GTKGtk_combo_box_get_active(this.Handle)
		var cond484 string
		if index != -1 {
			cond484 = this.GetItem(index)
		} else {
			cond484 = ""
		}
		return cond484
	}
}

func (this *Combo) GetTextStartEnd(start int32, stop int32) string {
	return jrt.Substring(this.GetText(), start, stop-1)
}

func (this *Combo) GetTextHeight() int32 {
	this.CheckWidget()
	var requisition gtk.GtkRequisition = gtk.GtkRequisition{}
	this.impl.gtk_widget_get_preferred_size_(this.Handle, &requisition)
	return requisition.Height
}
